INSERT INTO touite (users_id, content, note, posted_at) VALUES (12, 'La seance du jour confirme les progres de la semaine. Le detail le plus interessant reste a verifier. #sport #photographie #web. Cette observation porte le repere editorial 292.', 0, '2026-10-19 12:16:44');
INSERT INTO touite (users_id, content, note, posted_at) VALUES (13, 'Le roman ouvert hier construit une intrigue captivante. Cette petite decouverte meritait vraiment une publication. #lecture #humour #php. Cette observation porte le repere editorial 293.', 1, '2026-10-20 19:29:01');
INSERT INTO touite (users_id, content, note, media_description, media_path, posted_at) VALUES (14, 'Une partie rapide suffit a declencher une belle revanche. Je garde cette idee pour la prochaine etape. #jeux #projet #concert. Cette observation porte le repere editorial 294.', 2, 'Illustration cuisine du touite.', 'image/touite_media/cuisine.svg', '2026-10-21 11:42:18');
INSERT INTO touite (users_id, content, note, posted_at) VALUES (15, 'Le sujet du jour merite une lecture attentive et nuancee. Le resultat est simple mais beaucoup plus pratique. #actualite #python #quotidien. Cette observation porte le repere editorial 295.', -2, '2026-10-22 18:55:35');
INSERT INTO touite (users_id, content, note, posted_at) VALUES (16, 'La decouverte de ce quartier reserve une surprise a chaque rue. Quelques essais ont suffi pour trouver la bonne approche. #voyage #linux #code. Cette observation porte le repere editorial 296.', -1, '2026-10-23 10:08:52');
INSERT INTO touite (users_id, content, note, media_description, media_path, posted_at) VALUES (17, 'Un changement de contraste ameliore immediatement la lisibilite. Cela donne envie de poursuivre la discussion avec la communaute. #design #podcast #nature. Cette observation porte le repere editorial 297.', 0, 'Illustration science du touite.', 'image/touite_media/science.svg', '2026-10-24 17:21:09');
INSERT INTO touite (users_id, content, note, posted_at) VALUES (18, 'Une requete SQL bien indexee repond beaucoup plus rapidement. Je partage ce retour apres une matinee bien remplie. #sql #cinema #vacances. Cette observation porte le repere editorial 298.', 1, '2026-10-25 09:34:26');
INSERT INTO touite (users_id, content, note, posted_at) VALUES (19, 'Le nouvel episode relance une intrigue que lon croyait terminee. Une amelioration modeste change pourtant toute lexperience. #serie #musique #etudes. Cette observation porte le repere editorial 299.', 2, '2026-10-26 16:47:43');
INSERT INTO touite (users_id, content, note, media_description, media_path, posted_at) VALUES (20, 'La maintenance du service est annoncee avec un horaire precis. Ce souvenir restera associe a une journee pleine de curiosite. #annonce #technologie #science. Cette observation porte le repere editorial 300.', -2, 'Illustration actualite du touite.', 'image/touite_media/actualite.svg', '2026-10-27 08:00:00');
